def _align_to_newline(self):
    fo, bsize = self._file_obj, self._blocksize
    while True:
        start = fo.tell()
        block = fo.read(bsize)
        if not block:
            return
        newline = b'\n' if isinstance(block, bytes) else '\n'
        offset = block.find(newline)
        if offset >= 0:
            fo.seek(start + offset)
            return

